import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static int nextInt() {
        while (buf[pos] <= ' ') pos++;
        int r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        // forbidden[b] = largest a < b that conflicts with b.
        int[] forbidden = new int[n + 1];
        for (int i = 0; i < m; i++) {
            int a = nextInt(), b = nextInt();
            if (a > b) {
                int t = a;
                a = b;
                b = t;
            }
            forbidden[b] = Math.max(forbidden[b], a);
        }
        long left = 1, answer = 0;
        for (int right = 1; right <= n; right++) {
            left = Math.max(left, forbidden[right] + 1);
            answer += right - left + 1;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	pos := 0
	nextInt := func() int {
		for data[pos] <= ' ' {
			pos++
		}
		r := 0
		for pos < len(data) && data[pos] > ' ' {
			r = r*10 + int(data[pos]-'0')
			pos++
		}
		return r
	}
	n, m := nextInt(), nextInt()
	// forbidden[b] = largest a < b that conflicts with b.
	forbidden := make([]int, n+1)
	for i := 0; i < m; i++ {
		a, b := nextInt(), nextInt()
		if a > b {
			a, b = b, a
		}
		forbidden[b] = max(forbidden[b], a)
	}
	left, answer := 1, int64(0)
	for right := 1; right <= n; right++ {
		left = max(left, forbidden[right]+1)
		answer += int64(right - left + 1)
	}
	fmt.Println(answer)
}
